{"path": "/tmp/check.py", "content": "import ast
import builtins
import inspect
import os
import sys

ROOT = "/app/tally/reports"
LAYER = {"__init__": 6, "errors": 0, "tables": 0, "state": 0, "system": 0, "formatting": 1, "model": 1, "loading": 2,
         "aggregate": 3, "renderers": 4, "cli": 5}

mods = {}
for dp, dn, fn in os.walk(ROOT):
    dn[:] = [d for d in dn if d != "__pycache__"]
    for f in fn:
        if f.endswith(".py"):
            p = os.path.join(dp, f)
            rel = os.path.relpath(p, ROOT)[:-3].split(os.sep)
            if rel[-1] == "__init__":
                rel = rel[:-1]
            name = ".".join(["tally", "reports"] + rel)
            mods[name] = p
isinit = {n for n, p in mods.items() if p.endswith("__init__.py")}


def layer(name):
    parts = name.split(".")
    if len(parts) == 2:
        return 6
    return LAYER[parts[2]]


problems = []
graph = {}
for name, p in mods.items():
    src = open(p, encoding="utf-8").read()
    n = src.count("\n") + (0 if src.endswith("\n") else 1)
    if n > 400:
        problems.append(f"{name}: {n} lines")
    tree = ast.parse(src)
    pkg = name if name in isinit else name.rsplit(".", 1)[0]
    deps = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                if a.name.startswith("tally"):
                    deps.add(a.name)
                if a.name in ("importlib",):
                    problems.append(f"{name}: importlib")
        elif isinstance(node, ast.ImportFrom):
            if node.level:
                base = pkg.split(".")
                base = base[: len(base) - (node.level - 1)]
                full = ".".join(base + ([node.module] if node.module else []))
            else:
                full = node.module or ""
            if full == "importlib" or (node.module or "").startswith("importlib"):
                problems.append(f"{name}: importlib")
            if full.startswith("tally"):
                for a in node.names:
                    cand = full + "." + a.name
                    deps.add(cand if cand in mods else full)
            elif full and full.split(".")[0] == "tally":
                pass
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "__import__":
            problems.append(f"{name}: __import__")
    # imports of tally outside reports
    for d in deps:
        if not d.startswith("tally.reports"):
            problems.append(f"{name}: imports {d}")
    graph[name] = deps
    for d in deps:
        if d in mods or d == "tally.reports":
            if layer(d) > layer(name):
                problems.append(f"{name} (L{layer(name)}) imports {d} (L{layer(d)})")
        else:
            problems.append(f"{name}: unresolved import {d}")


# cycles
def find_cycle():
    color = {}
    stack = []

    def dfs(u):
        color[u] = 1
        stack.append(u)
        for v in graph.get(u, ()):
            if v not in graph:
                continue
            if color.get(v) == 1:
                return stack[stack.index(v):] + [v]
            if color.get(v) is None:
                r = dfs(v)
                if r:
                    return r
        stack.pop()
        color[u] = 2
        return None

    for n in graph:
        if color.get(n) is None:
            r = dfs(n)
            if r:
                return r


cyc = find_cycle()
if cyc:
    problems.append("cycle: " + " -> ".join(cyc))
# a package importing its own submodule that imports back: implicit parent import is not counted

# undefined names / unused imports
for name, p in mods.items():
    tree = ast.parse(open(p, encoding="utf-8").read())
    defined = set(dir(builtins)) | {"__name__", "__file__"}
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for a in node.names:
                nm = (a.asname or a.name).split(".")[0]
                defined.add(nm)
                imported[nm] = node.lineno
        elif isinstance(node, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)):
            defined.add(node.name)
            if not isinstance(node, ast.ClassDef):
                for a in node.args.args + node.args.kwonlyargs + node.args.posonlyargs:
                    defined.add(a.arg)
                if node.args.vararg:
                    defined.add(node.args.vararg.arg)
                if node.args.kwarg:
                    defined.add(node.args.kwarg.arg)
        elif isinstance(node, ast.Lambda):
            for a in node.args.args:
                defined.add(a.arg)
        elif isinstance(node, ast.Name) and isinstance(node.ctx, (ast.Store, ast.Del)):
            defined.add(node.id)
        elif isinstance(node, ast.ExceptHandler) and node.name:
            defined.add(node.name)
    used = set()
    strs = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
            used.add(node.id)
            if node.id not in defined:
                problems.append(f"{name}:{node.lineno}: undefined {node.id}")
    # annotations are strings under __future__; scan them textually
    src = open(p, encoding="utf-8").read()
    for node in ast.walk(tree):
        ann = []
        if isinstance(node, ast.FunctionDef):
            ann = [a.annotation for a in node.args.args + node.args.kwonlyargs if a.annotation] + ([node.returns] if node.returns else [])
        elif isinstance(node, ast.AnnAssign):
            ann = [node.annotation]
        for a in ann:
            for sub in ast.walk(a):
                if isinstance(sub, ast.Name):
                    used.add(sub.id)
                    if sub.id not in defined:
                        problems.append(f"{name}:{sub.lineno}: undefined (annotation) {sub.id}")
                elif isinstance(sub, ast.Constant) and isinstance(sub.value, str):
                    try:
                        for s2 in ast.walk(ast.parse(sub.value, mode="eval")):
                            if isinstance(s2, ast.Name):
                                used.add(s2.id)
                    except SyntaxError:
                        pass
    if not name.endswith("reports") and name != "tally.reports":
        for nm, ln in imported.items():
            if nm not in used and nm != "annotations":
                if not p.endswith("__init__.py"):
                    problems.append(f"{name}:{ln}: unused import {nm}")

# state variables: top-level assigned in exactly one module
for var in ["_LOCALE", "_CURRENCY", "_FMT_CACHE", "_WIDTH_CACHE", "_WARNINGS"]:
    homes = []
    for name, p in mods.items():
        for node in ast.parse(open(p, encoding="utf-8").read()).body:
            if isinstance(node, (ast.Assign, ast.AnnAssign)):
                tg = node.targets if isinstance(node, ast.Assign) else [node.target]
                if any(isinstance(t, ast.Name) and t.id == var for t in tg):
                    homes.append(name)
    if len(homes) != 1:
        problems.append(f"{var} homes {homes}")
    for name, p in mods.items():
        src = open(p, encoding="utf-8").read()
        if name != "tally.reports.state":
            for i, line in enumerate(src.split("\n"), 1):
                import re
                if re.search(r"(?<![\w.])" + var + r"\b", line):
                    problems.append(f"{name}:{i}: bare {var}")
# any `from .. import _x` of state private names
for name, p in mods.items():
    for node in ast.walk(ast.parse(open(p, encoding="utf-8").read())):
        if isinstance(node, ast.ImportFrom) and (node.module or "").endswith("state"):
            for a in node.names:
                if a.name.startswith("_"):
                    problems.append(f"{name}: from state import {a.name}")

# __init__ only docstring/imports/__all__
t = ast.parse(open(ROOT + "/__init__.py", encoding="utf-8").read())
for i, node in enumerate(t.body):
    if i == 0 and isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant):
        continue
    if isinstance(node, (ast.Import, ast.ImportFrom)):
        continue
    if isinstance(node, ast.Assign) and [x.id for x in node.targets] == ["__all__"]:
        continue
    problems.append(f"__init__: disallowed statement line {node.lineno}")

print("\n".join(problems) or "no structural problems")
"}

{"path": "/tmp/api.py", "content": "import ast
import inspect
import json
import sys

tree = sys.argv[1]
sys.path.insert(0, tree)
import tally.reports as r

src = open("/tmp/orig/app/tally/reports.py", encoding="utf-8").read()
t = ast.parse(src)
names = []
privs = []
for node in t.body:
    got = []
    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
        got = [node.name]
    elif isinstance(node, ast.Assign):
        got = [x.id for x in node.targets if isinstance(x, ast.Name)]
    elif isinstance(node, ast.AnnAssign):
        got = [node.target.id]
    for n in got:
        (names if not n.startswith("_") else privs).append(n)
out = {}
for n in names:
    o = getattr(r, n)
    if inspect.isclass(o):
        try:
            sig = str(inspect.signature(o))
        except Exception as e:
            sig = repr(e)
        out[n] = ["class", sig, o.__module__, [c.__name__ for c in o.__mro__]]
    elif inspect.isfunction(o):
        out[n] = ["func", str(inspect.signature(o)), [(p.name, str(p.kind), repr(p.default)) for p in inspect.signature(o).parameters.values()]]
    else:
        out[n] = ["const", repr(o)]
out["__all__"] = list(r.__all__)
out["__private_present"] = [p for p in privs if hasattr(r, p)]
out["__doc__"] = r.__doc__
print(json.dumps(out, indent=1, sort_keys=True))
"}

